#include <bits/stdc++.h>
using namespace std;

class Session {
public:
    string name;
    Session(string name) : name(name) {}
};

class SessionCache {
public:
    static vector<shared_ptr<Session>> sessions;   // never cleared

    static void addSession(shared_ptr<Session> s) {
        sessions.push_back(s);   // never removed anywhere
    }
};
vector<shared_ptr<Session>> SessionCache::sessions;
// every Session ever created stays reachable through the static vector,
// so its memory is never reclaimed until the program itself ends

int main() {
    SessionCache::addSession(make_shared<Session>("user-1"));
    SessionCache::addSession(make_shared<Session>("user-2"));
    cout << SessionCache::sessions.size() << endl;
    return 0;
}

